UPDATE ORDERS
SET ORDER_STATUS = 'REFUNDED',
    CANCEL_REASON = #{cancelReason}
WHERE TOSS_ORDER_ID = #{tossOrderId}

UPDATE ORDERS
SET ORDER_STATUS = 'DONE',
    CONFIRMED_AT = #{confirmedAt}
WHERE ORDER_ID     = #{orderId}
  AND MEMBER_ID    = #{memberId}
  AND ORDER_STATUS = 'SHIPPED'

